(1015778, 122194, 24613, '<td valign="top">Great shadow!  Looking at this photo makes me tap my feet!! 9</td>', 'Great shadow!  Looking at this photo makes me tap my feet!! 9', '2004-11-17 08:21:36.000000', NULL, 1),
(1015779, 121645, 29079, '<td valign="top">funny :)</td>', 'funny :)', '2004-11-17 08:22:10.000000', NULL, 1),
