(1016045, 120744, 28337, '<td valign="top">the sky looks burned out</td>', 'the sky looks burned out', '2004-11-17 10:04:12.000000', NULL, 1),
(1016046, 122030, 29573, '<td valign="top">I happen to love children and pets, you have captured a great expression which is very hard to do with animals.</td>', 'I happen to love children and pets, you have captured a great expression which is very hard to do with animals.', '2004-11-17 10:04:22.000000', NULL, 1),
