(1016080, 121492, 29148, '<td valign="top">Why do I feel fuzzy?</td>', 'Why do I feel fuzzy?', '2004-11-17 10:20:16.000000', NULL, 1),
(1016082, 122049, 208, '<td valign="top">I like the DOF. Good choice for a b&amp;w.</td>', 'I like the DOF. Good choice for a b&w.', '2004-11-17 10:20:50.000000', NULL, 1),
(1016083, 121581, 29573, '<td valign="top">Wow....those eyes!</td>', 'Wow....those eyes!', '2004-11-17 10:20:55.000000', NULL, 1),
