INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1016758, 121551, 25024, '<td valign="top">I''m sorry but memories of what? Could you have brightened up a little to make more of those edge lights on the dark rope?</td>', 'I''m sorry but memories of what? Could you have brightened up a little to make more of those edge lights on the dark rope?', '2004-11-17 13:24:24.000000', NULL, 1),
(1016759, 121633, 24911, '<td valign="top">Nice idea I do wish I new what they are looking at. This way I am not sure what the subject is...</td>', 'Nice idea I do wish I new what they are looking at. This way I am not sure what the subject is...', '2004-11-17 13:24:27.000000', NULL, 1),
(1016760, 121639, 24911, '<td valign="top">Nice shot. A little bit too centered INHO.</td>', 'Nice shot. A little bit too centered INHO.', '2004-11-17 13:25:43.000000', NULL, 1),
(1016762, 120582, 3087, '<td valign="top">Nice side view and I like the blurred but textured background. The lenses of the specs seem a bit strange, perhaps it''s just because they are so thick and it''s a shame the glasses stem crosses just where his eye is but... it''s does make it more anonymous which isn''t a bad thing. Nice work!</td>', 'Nice side view and I like the blurred but textured background. The lenses of the specs seem a bit strange, perhaps it''s just because they are so thick and it''s a shame the glasses stem crosses just where his eye is but... it''s does make it more anonymous which isn''t a bad thing. Nice work!', '2004-11-17 13:26:24.000000', NULL, 1),
(1016763, 121389, 25024, '<td valign="top">I find this a little flat looking and think if you had taken it closer up at a more interesting angle it could have improved it.</td>', 'I find this a little flat looking and think if you had taken it closer up at a more interesting angle it could have improved it.', '2004-11-17 13:27:09.000000', NULL, 1),
(1016764, 121825, 27244, '<td valign="top">I like the lighting and angle.  I dont really like the pose for this crop.  I would prefer to see it without the hand on his chin, as it just does not seem natural.   I do enjoy the contrast of his shirt, amongst everything else in the photo.  -7-</td>', 'I like the lighting and angle.  I dont really like the pose for this crop.  I would prefer to see it without the hand on his chin, as it just does not seem natural.   I do enjoy the contrast of his shirt, amongst everything else in the photo.  -7-', '2004-11-17 13:27:34.000000', NULL, 1),
(1016767, 120429, 25024, '<td valign="top">I like the harsh lighting and stark contrast - it works for me. Hope you have equal success!</td>', 'I like the harsh lighting and stark contrast - it works for me. Hope you have equal success!', '2004-11-17 13:28:39.000000', NULL, 1),
(1016769, 121595, 3087, '<td valign="top">Certainly an interesting if somewhat bizaare idea. I like the detail of the bubbles and the high contrast on the die. Background is a little too grey - a separate light for the background might help.</td>', 'Certainly an interesting if somewhat bizaare idea. I like the detail of the bubbles and the high contrast on the die. Background is a little too grey - a separate light for the background might help.', '2004-11-17 13:29:11.000000', NULL, 1),
(1016770, 121969, 10432, '<td valign="top">This looks like a mug my friend has.  The secret is one of the top openings works like a straw!  Cool shadow!</td>', 'This looks like a mug my friend has.  The secret is one of the top openings works like a straw!  Cool shadow!', '2004-11-17 13:29:53.000000', NULL, 1),
(1016772, 122012, 25024, '<td valign="top">Sorry but your image is too small - its difficult to see what you are trying to convey here. 3</td>', 'Sorry but your image is too small - its difficult to see what you are trying to convey here. 3', '2004-11-17 13:30:40.000000', NULL, 1),
