INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1017451, 121104, 20066, '<td valign="top">blask and white and blue or is it perhaps just my eyes or computer?</td>', 'blask and white and blue or is it perhaps just my eyes or computer?', '2004-11-17 16:38:52.000000', NULL, 1),
(1017452, 120702, 7543, '<td valign="top">Very nice portrait, sharp and a great model. Her eyes do very much for this shot. Good composition, and nice shades of gray. Good job.</td>', 'Very nice portrait, sharp and a great model. Her eyes do very much for this shot. Good composition, and nice shades of gray. Good job.', '2004-11-17 16:38:55.000000', NULL, 1),
(1017455, 122204, 7291, '<td valign="top">Cool.  I see what you mean by the tite.</td>', 'Cool.  I see what you mean by the tite.', '2004-11-17 16:39:37.000000', NULL, 1),
(1017456, 121830, 27244, '<td valign="top">Dislike the angle...The top of the photo, which is cropped out is much more interesting and contrasting than the words of which the focus is on.  Since you cant read the entire word why include it?  Besides in the bottom right corner you have some detailing that does nothing for the picture so why leave it in?  -5-</td>', 'Dislike the angle...The top of the photo, which is cropped out is much more interesting and contrasting than the words of which the focus is on.  Since you cant read the entire word why include it?  Besides in the bottom right corner you have some detailing that does nothing for the picture so why leave it in?  -5-', '2004-11-17 16:39:45.000000', NULL, 1),
(1017461, 121941, 7543, '<td valign="top">A bit too much contrast for my taste, gives it a flat feeling.</td>', 'A bit too much contrast for my taste, gives it a flat feeling.', '2004-11-17 16:41:01.000000', NULL, 1),
(1017462, 122188, 7291, '<td valign="top">Awesome!  What a great location for a black &amp; white photo.</td>', 'Awesome!  What a great location for a black & white photo.', '2004-11-17 16:41:12.000000', NULL, 1),
(1017465, 121768, 27244, '<td valign="top">Good take!  I like how almost perfect the snow looks in the links of the fencing.  Good contrast and cropping.  -8-</td>', 'Good take!  I like how almost perfect the snow looks in the links of the fencing.  Good contrast and cropping.  -8-', '2004-11-17 16:42:01.000000', NULL, 1),
(1017466, 121378, 18191, '<td valign="top">I like the motion blur. A very unique and well excecuted idea. If she could have kept her head slightly more still it would have been a fantastic shot.</td>', 'I like the motion blur. A very unique and well excecuted idea. If she could have kept her head slightly more still it would have been a fantastic shot.', '2004-11-17 16:42:03.000000', NULL, 1),
(1017467, 120750, 7543, '<td valign="top">A bit over sharpened, evident on the outlines of the babies shoulders.</td>', 'A bit over sharpened, evident on the outlines of the babies shoulders.', '2004-11-17 16:42:08.000000', NULL, 1),
(1017471, 121374, 27574, '<td valign="top">Very Nice</td>', 'Very Nice', '2004-11-17 16:43:25.000000', NULL, 1),
(1017472, 121389, 27244, '<td valign="top">Perhaps the  photo would be better if you saw less of the ground leading in and a little more of the sky... -7-</td>', 'Perhaps the  photo would be better if you saw less of the ground leading in and a little more of the sky... -7-', '2004-11-17 16:43:35.000000', NULL, 1),
(1017475, 120837, 13749, '<td valign="top">very interesting look to it, with great composition.</td>', 'very interesting look to it, with great composition.', '2004-11-17 16:44:11.000000', NULL, 1),
(1017476, 121063, 18191, '<td valign="top">A very powerful shot that is well done. This could almost pass for objective photography which I think we should have more of here on DPC. Good job here.</td>', 'A very powerful shot that is well done. This could almost pass for objective photography which I think we should have more of here on DPC. Good job here.', '2004-11-17 16:44:33.000000', NULL, 1),
(1017478, 121148, 7543, '<td valign="top">A very retro looking shot. Great post processing job.</td>', 'A very retro looking shot. Great post processing job.', '2004-11-17 16:44:48.000000', NULL, 1),
(1017479, 121992, 7291, '<td valign="top">As a suggestion, you could have used to the Channel Mixer in PS to simulate a red filter and that would have made the apples much brighter giving this more contrast.  Just a thought.</td>', 'As a suggestion, you could have used to the Channel Mixer in PS to simulate a red filter and that would have made the apples much brighter giving this more contrast.  Just a thought.', '2004-11-17 16:44:49.000000', NULL, 1),
(1017480, 121637, 27244, '<td valign="top">I like this picture alot.  Nice contrast of the black and white.  Nice textures, and composition.  -10-</td>', 'I like this picture alot.  Nice contrast of the black and white.  Nice textures, and composition.  -10-', '2004-11-17 16:45:52.000000', NULL, 1),
(1017481, 122194, 7291, '<td valign="top">Nice.  Good use shadows.</td>', 'Nice.  Good use shadows.', '2004-11-17 16:46:14.000000', NULL, 1),
(1017482, 121481, 7543, '<td valign="top">A bit dark, took me a few seconds and viewing the screen from many postitions before I found out what it is. Still can''t figure the whole frame out.</td>', 'A bit dark, took me a few seconds and viewing the screen from many postitions before I found out what it is. Still can''t figure the whole frame out.', '2004-11-17 16:46:30.000000', NULL, 1),
