(1017488, 120995, 20679, '<td valign="top">nice shot but wish it was bigger</td>', 'nice shot but wish it was bigger', '2004-11-17 16:47:47.000000', NULL, 1),
(1017489, 121158, 7543, '<td valign="top">A bit soft for my taste (no pun intended). Great lighting, backlight gives the shot a whole other dimension. Good job.</td>', 'A bit soft for my taste (no pun intended). Great lighting, backlight gives the shot a whole other dimension. Good job.', '2004-11-17 16:47:58.000000', NULL, 1),
(1017490, 120701, 27244, '<td valign="top">The only thing I dislike about this photo is the top of the other tree.  But I figure that there was probably no way to get it out of frame.  -7-</td>', 'The only thing I dislike about this photo is the top of the other tree.  But I figure that there was probably no way to get it out of frame.  -7-', '2004-11-17 16:47:58.000000', NULL, 1),
