(1017537, 122194, 26526, '<td valign="top">Outstanding use of lighting! The shadow makes (is) this photo, as does b&amp;w. Great charactor study.  Like the grain in it. The spots may be a tad distracting, but gets a high score from me! Well done.</td>', 'Outstanding use of lighting! The shadow makes (is) this photo, as does b&w. Great charactor study.  Like the grain in it. The spots may be a tad distracting, but gets a high score from me! Well done.', '2004-11-17 17:02:28.000000', NULL, 1),
(1017541, 120654, 22010, '<td valign="top">Not sure about the cropping. A bit tight for me. Good backlighting.</td>', 'Not sure about the cropping. A bit tight for me. Good backlighting.', '2004-11-17 17:03:16.000000', NULL, 1),
(1017544, 122156, 7364, '<td valign="top">That cat will get a brain tumor from laying on router!</td>', 'That cat will get a brain tumor from laying on router!', '2004-11-17 17:03:30.000000', NULL, 1),
