(1017582, 122183, 22010, '<td valign="top">Clever. Great idea, great execution. 8</td>', 'Clever. Great idea, great execution. 8', '2004-11-17 17:12:56.000000', NULL, 1),
(1017583, 120870, 26526, '<td valign="top">Looks like a snapshot of a child that doesn''t want his picture taken. Nothing really interesting going on in this photo to get my attention.</td>', 'Looks like a snapshot of a child that doesn''t want his picture taken. Nothing really interesting going on in this photo to get my attention.', '2004-11-17 17:13:20.000000', NULL, 1),
(1017585, 120389, 22010, '<td valign="top">Wow, that must''ve been some sight in person. Nice capture. The houses are a bit dark though. They have to be there for context of course. Good luck.</td>', 'Wow, that must''ve been some sight in person. Nice capture. The houses are a bit dark though. They have to be there for context of course. Good luck.', '2004-11-17 17:14:12.000000', NULL, 1),
