(1018229, 121812, 24065, '<td valign="top">I like the photo and the title :D</td>', 'I like the photo and the title :D', '2004-11-17 19:53:47.000000', NULL, 1),
(1018230, 121159, 18834, '<td valign="top">I like the silohuette of the metal on the window and the flower caused by light from outside.  Also, excellent title.  The idea is perfect for a b/w challenge.</td>', 'I like the silohuette of the metal on the window and the flower caused by light from outside.  Also, excellent title.  The idea is perfect for a b/w challenge.', '2004-11-17 19:54:03.000000', NULL, 1),
