(1020313, 121530, 28337, '<td valign="top">good picture but a  bit too much sky</td>', 'good picture but a  bit too much sky', '2004-11-18 17:33:47.000000', NULL, 1),
(1020317, 121135, 28770, '<td valign="top">i wouldve gotten a lower angle so the distance btwn the first and second rows wasnt fo predominant, othewise i love it</td>', 'i wouldve gotten a lower angle so the distance btwn the first and second rows wasnt fo predominant, othewise i love it', '2004-11-18 17:36:33.000000', NULL, 1),
