(1020719, 122115, 11800, '<td valign="top">Nice astudy of form.</td>', 'Nice astudy of form.', '2004-11-18 20:59:38.000000', NULL, 1),
(1020723, 121040, 18799, '<td valign="top">Way too noisy.  I think it may have been better if the focus was on the foreground for this shot.  I''m not entirely sure what he''s doing.</td>', 'Way too noisy.  I think it may have been better if the focus was on the foreground for this shot.  I''m not entirely sure what he''s doing.', '2004-11-18 21:01:06.000000', NULL, 1),
