INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1022080, 121467, 28540, '<td valign="top">seagulls are so pesky=)</td>', 'seagulls are so pesky=)', '2004-11-19 12:20:35.000000', NULL, 1),
