(1022843, 121866, 25397, '<td valign="top">Very creepy...And amazing!</td>', 'Very creepy...And amazing!', '2004-11-19 19:08:16.000000', NULL, 1),
(1022844, 121263, 11800, '<td valign="top">Lovely study of shadows.</td>', 'Lovely study of shadows.', '2004-11-19 19:08:22.000000', NULL, 1),
