(1023408, 121224, 9668, '<td valign="top">Intriguing clouds, nice use of parellel lines (close to it).</td>', 'Intriguing clouds, nice use of parellel lines (close to it).', '2004-11-19 23:31:05.000000', NULL, 1),
(1023413, 120562, 27842, '<td valign="top">Nice composition and contrast</td>', 'Nice composition and contrast', '2004-11-19 23:31:50.000000', NULL, 1),
