(1023423, 122042, 9668, '<td valign="top">I know how hard it may have been to get this sharp of an action image that includes the golf ball in it. Well done!</td>', 'I know how hard it may have been to get this sharp of an action image that includes the golf ball in it. Well done!', '2004-11-19 23:34:18.000000', NULL, 1),
(1023425, 120623, 9668, '<td valign="top">Nice gradient pattern, but the shot isn''t that exciting overall.</td>', 'Nice gradient pattern, but the shot isn''t that exciting overall.', '2004-11-19 23:34:42.000000', NULL, 1),
(1023429, 122200, 27842, '<td valign="top">Nice movement and contrast</td>', 'Nice movement and contrast', '2004-11-19 23:35:20.000000', NULL, 1),
(1023431, 121985, 9668, '<td valign="top">Nice use of soft focus. Good pose.</td>', 'Nice use of soft focus. Good pose.', '2004-11-19 23:35:50.000000', NULL, 1),
(1023432, 122083, 9668, '<td valign="top">Cool angle, don''t really like the tilt.</td>', 'Cool angle, don''t really like the tilt.', '2004-11-19 23:36:24.000000', NULL, 1),
