(1024581, 122046, 9668, '<td valign="top">Fun action shot.</td>', 'Fun action shot.', '2004-11-20 18:34:30.000000', NULL, 1),
(1024582, 121646, 9668, '<td valign="top">Nice sillhoutte. I like the cross in the background, adds alot of depth.</td>', 'Nice sillhoutte. I like the cross in the background, adds alot of depth.', '2004-11-20 18:35:06.000000', NULL, 1),
(1024583, 120840, 20115, '<td valign="top">I really like this--but I would want to see more of the boat and the water.</td>', 'I really like this--but I would want to see more of the boat and the water.', '2004-11-20 18:35:09.000000', NULL, 1),
