INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1027095, 122206, 29255, '<td valign="top">Maybe the trash noise fits this one, but still, I don''t like it.</td>', 'Maybe the trash noise fits this one, but still, I don''t like it.', '2004-11-22 09:58:28.000000', NULL, 1),
