(1027738, 121595, 29535, '<td valign="top">That''s bloody brilliant man, well done.  Really creative.</td>', 'That''s bloody brilliant man, well done.  Really creative.', '2004-11-22 17:33:02.000000', NULL, 1),
(1027739, 121454, 29535, '<td valign="top">Brilliant reflections, well done!</td>', 'Brilliant reflections, well done!', '2004-11-22 17:33:25.000000', NULL, 1),
