INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1028477, 121699, 27767, '<td valign="top">I like the panorama view in this shot. I also like the gradient sky and the silhouettes against the bright horizon.  Looks very pleasent.</td>', 'I like the panorama view in this shot. I also like the gradient sky and the silhouettes against the bright horizon.  Looks very pleasent.', '2004-11-23 06:48:25.000000', NULL, 1),
(1028481, 121242, 27767, '<td valign="top">Nice sharp focus.  The light streaks coming from the center of the flower give a nice contrast to the image.</td>', 'Nice sharp focus.  The light streaks coming from the center of the flower give a nice contrast to the image.', '2004-11-23 06:54:04.000000', NULL, 1),
(1028489, 122102, 27767, '<td valign="top">Great composition including the body in the background. The nice soft white contrasts nicely with the dark blacks.</td>', 'Great composition including the body in the background. The nice soft white contrasts nicely with the dark blacks.', '2004-11-23 07:05:15.000000', NULL, 1),
(1028490, 122020, 27767, '<td valign="top">I like the detailed lighting and shadows.  The starred lights are a nice touch too.</td>', 'I like the detailed lighting and shadows.  The starred lights are a nice touch too.', '2004-11-23 07:09:28.000000', NULL, 1),
(1028492, 121075, 27767, '<td valign="top">I know that feeling :)  I wonder if cropping off some of the open sky and a small amount of the foreground could help give this image more impact.  The broad wings I think would work well in a very wide shot.</td>', 'I know that feeling :)  I wonder if cropping off some of the open sky and a small amount of the foreground could help give this image more impact.  The broad wings I think would work well in a very wide shot.', '2004-11-23 07:11:43.000000', NULL, 1),
(1028494, 121487, 27767, '<td valign="top">Very neat effect on this shot.  I really like the relatively uncluttered ground which leaves the tree trunks to be focused on.</td>', 'Very neat effect on this shot.  I really like the relatively uncluttered ground which leaves the tree trunks to be focused on.', '2004-11-23 07:16:01.000000', NULL, 1),
(1028495, 121901, 27767, '<td valign="top">The splash is pretty cool, but the shot feels surprisingly static with the dead center subject and framing.  Maybe a tighter crop, or different composition would bring out the action more.</td>', 'The splash is pretty cool, but the shot feels surprisingly static with the dead center subject and framing.  Maybe a tighter crop, or different composition would bring out the action more.', '2004-11-23 07:18:53.000000', NULL, 1),
(1028496, 122151, 27767, '<td valign="top">Great dramatic clouds.  I like how the road and the building are placed out of center.</td>', 'Great dramatic clouds.  I like how the road and the building are placed out of center.', '2004-11-23 07:20:52.000000', NULL, 1),
